import {copyFile, mkdir, readFile, readdir} from 'node:fs/promises';
import {dirname, join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {staticPrefetchRoutes, staticPrefetchEntries, prefetchAssetDirectory} from './static-prefetch-routes.mjs';

// EdgeOne's adapter currently copies full .rsc files, but not Next 16's segment
// files. Keep the framework-generated bytes intact and publish them as assets.
export async function prepareStaticPrefetch({buildDirectory='.next'}={}) {
  const buildId=(await readFile(join(buildDirectory,'BUILD_ID'),'utf8')).trim();
  if(!/^[a-f0-9]{40}$/.test(buildId))throw new Error('PREFETCH_BUILD_ID_INVALID');
  const manifest=JSON.parse(await readFile(join(buildDirectory,'prerender-manifest.json'),'utf8'));
  let files=0;
  for(const route of staticPrefetchRoutes) {
    if(manifest.routes[route]?.initialRevalidateSeconds!==false)throw new Error(`PREFETCH_ROUTE_NOT_STATIC: ${route}`);
    const routeKey=route==='/'?'index':route.slice(1);
    const source=join(buildDirectory,'server/app',routeKey+'.segments');
    const treeBody=await readFile(join(source,'_tree.segment.rsc'),'utf8');
    const root=treeBody.split('\n').find(line=>line.startsWith('0:'));
    const tree=root?JSON.parse(root.slice(2)):null;
    if(!tree?.tree||tree.buildId!==buildId)throw new Error(`PREFETCH_TREE_INVALID: ${route}`);
    const expected=new Set(staticPrefetchEntries.filter(entry=>entry.source===route).map(entry=>entry.segment));
    async function copySegments(directory,relative='') {
      for(const entry of await readdir(directory,{withFileTypes:true})) {
        if(entry.isDirectory())await copySegments(join(directory,entry.name),join(relative,entry.name));
        else if(entry.isFile()&&entry.name.endsWith('.segment.rsc')) {
          const segment=join(relative,entry.name.replace(/\.segment\.rsc$/,'')).replaceAll('\\','/');
          if(!expected.delete(segment))throw new Error(`PREFETCH_SEGMENT_MAP_CHANGED: ${route} ${segment}`);
          const destination=join(buildDirectory,'static',buildId,prefetchAssetDirectory,routeKey,relative,entry.name.replace(/\.segment\.rsc$/,'.rsc'));
          await mkdir(dirname(destination),{recursive:true});
          await copyFile(join(directory,entry.name),destination);
          files++;
        }
      }
    }
    await copySegments(source);
    if(expected.size)throw new Error(`PREFETCH_SEGMENT_MAP_CHANGED: ${route} missing ${[...expected].join(',')}`);
  }
  return {buildId,routes:staticPrefetchRoutes.length,files};
}

if(process.argv[1]&&fileURLToPath(import.meta.url)===process.argv[1]) {
  const result=await prepareStaticPrefetch();
  process.stdout.write(`Prepared static prefetch: ${result.routes} routes, ${result.files} files\n`);
}
